namespace
{
    bool ReadVec(const TSharedPtr<FJsonObject>& Obj, const FString& Field, FVector& OutUE)
    {
        const TArray<TSharedPtr<FJsonValue>>* Arr = nullptr;
        if (!Obj.IsValid() || !Obj->TryGetArrayField(Field, Arr) || Arr->Num() < 3) return false;
        OutUE = MojuloScore::P((*Arr)[0]->AsNumber(), (*Arr)[1]->AsNumber(), (*Arr)[2]->AsNumber());
        return true;
    }

    TSharedPtr<FJsonObject> ParseFile(const FString& Path)
    {
        FString Text;
        if (!FFileHelper::LoadFileToString(Text, *Path)) return nullptr;
        TSharedPtr<FJsonObject> Root;
        const TSharedRef<TJsonReader<>> Reader = TJsonReaderFactory<>::Create(Text);
        if (!FJsonSerializer::Deserialize(Reader, Root)) return nullptr;
        return Root;
    }

    FString ProgressPath() { return FPaths::ProjectSavedDir() / TEXT("mojulo.completed"); }
}

namespace MojuloScore
{
    FVector P(double X, double Y, double Z)
    {
        return FVector(X * 100.0, -Y * 100.0, Z * 100.0);
    }

    FString MapPath(const FString& MapName)
    {
        FString Root;
        if (GConfig) GConfig->GetString(TEXT("Mojulo"), TEXT("MapRoot"), Root, GGameIni);
        Root.RemoveFromEnd(TEXT("/"));
        if (Root.StartsWith(TEXT("/Game/")))
        {
            const FString ProjectMap = Root / MapName;
            if (FPackageName::DoesPackageExist(ProjectMap)) return ProjectMap;
        }
        return FString(TEXT("/Game/MojuloPack/Maps/")) + MapName;
    }

    FString PackDir() { return FPaths::ProjectDir() / TEXT("MojuloPack"); }

    FString ScorePathForMap(const FString& MapName)
    {
        const FString PerLevel = PackDir() / TEXT("levels") / MapName / TEXT("score.json");
        if (FPaths::FileExists(PerLevel)) return PerLevel;
        return PackDir() / TEXT("score.json"); // world scope (U0 pack shape)
    }

    bool LoadScore(const FString& JsonPath, FMojuloScoreData& Out)
    {
        const TSharedPtr<FJsonObject> Root = ParseFile(JsonPath);
        if (!Root.IsValid()) return false;
        Root->TryGetStringField(TEXT("title"), Out.Title);
        ReadVec(Root, TEXT("spawn"), Out.Spawn);
        double Num = 0.0;
        if (Root->TryGetNumberField(TEXT("eye"), Num)) Out.Eye = Num;
        if (Root->TryGetNumberField(TEXT("ground"), Num)) Out.Ground = Num;
        Root->TryGetStringField(TEXT("player"), Out.Player);
        Root->TryGetStringField(TEXT("soundtrack"), Out.Soundtrack);

        const TArray<TSharedPtr<FJsonValue>>* Colliders = nullptr;
        if (Root->TryGetArrayField(TEXT("colliders"), Colliders) && Colliders->Num() > 0)
        {
            Out.bHasColliders = true;
            Out.MinColliderZ = TNumericLimits<float>::Max();
            for (const TSharedPtr<FJsonValue>& V : *Colliders)
            {
                const TSharedPtr<FJsonObject> C = V->AsObject();
                const TArray<TSharedPtr<FJsonValue>>* Min = nullptr;
                if (C.IsValid() && C->TryGetArrayField(TEXT("min"), Min) && Min->Num() >= 3)
                    Out.MinColliderZ = FMath::Min(Out.MinColliderZ, (float)(*Min)[2]->AsNumber());
            }
        }

        const TArray<TSharedPtr<FJsonValue>>* Entities = nullptr;
        if (Root->TryGetArrayField(TEXT("entities"), Entities))
            for (const TSharedPtr<FJsonValue>& V : *Entities)
            {
                const TSharedPtr<FJsonObject> E = V->AsObject();
                if (!E.IsValid()) continue;
                FMojuloEntity Entity;
                E->TryGetStringField(TEXT("id"), Entity.Id);
                E->TryGetStringField(TEXT("figure"), Entity.Figure);
                Entity.bHasTranslation = ReadVec(E, TEXT("translation"), Entity.Pos);
                const TSharedPtr<FJsonObject>* Loco = nullptr;
                if (E->TryGetObjectField(TEXT("locomotion"), Loco) && Loco->IsValid())
                {
                    (*Loco)->TryGetStringField(TEXT("idle"), Entity.IdleClip);
                    (*Loco)->TryGetStringField(TEXT("walk"), Entity.WalkClip);
                    (*Loco)->TryGetStringField(TEXT("boost"), Entity.BoostClip);
                }
                Out.Entities.Add(Entity);
            }

        // The mechanics vocabulary — defaults mirror Unity's MojuloLevel.cs
        // [Serializable] classes exactly (radius 2 m, planar true, pickup
        // 1.4 m, hazard 1.5 m / 20 dmg, survive 30 s, startHp 100).
        const TArray<TSharedPtr<FJsonValue>>* Mechanics = nullptr;
        if (Root->TryGetArrayField(TEXT("mechanics"), Mechanics))
            for (const TSharedPtr<FJsonValue>& V : *Mechanics)
            {
                const TSharedPtr<FJsonObject> M = V->AsObject();
                if (!M.IsValid()) continue;
                FString Kind;
                M->TryGetStringField(TEXT("kind"), Kind);
                if (Kind == TEXT("reach-exit"))
                {
                    FMojuloZone Zone;
                    ReadVec(M, TEXT("at"), Zone.Pos);
                    const TArray<TSharedPtr<FJsonValue>>* Half = nullptr;
                    if (M->TryGetArrayField(TEXT("half"), Half) && Half->Num() >= 3)
                    {
                        Zone.bHasHalf = true;
                        Zone.Half = FVector((*Half)[0]->AsNumber() * 100.0, (*Half)[1]->AsNumber() * 100.0, (*Half)[2]->AsNumber() * 100.0);
                    }
                    if (M->TryGetNumberField(TEXT("radius"), Num)) Zone.Radius = Num * 100.0;
                    M->TryGetBoolField(TEXT("planar"), Zone.bPlanar);
                    Out.Exits.Add(Zone);
                }
                else if (Kind == TEXT("collect"))
                {
                    const TArray<TSharedPtr<FJsonValue>>* Pickups = nullptr;
                    if (M->TryGetArrayField(TEXT("pickups"), Pickups))
                        for (const TSharedPtr<FJsonValue>& PV : *Pickups)
                        {
                            const TSharedPtr<FJsonObject> PO = PV->AsObject();
                            if (!PO.IsValid()) continue;
                            FMojuloPickup Pickup;
                            PO->TryGetStringField(TEXT("item"), Pickup.Item);
                            ReadVec(PO, TEXT("at"), Pickup.Pos);
                            if (PO->TryGetNumberField(TEXT("radius"), Num)) Pickup.Radius = Num * 100.0;
                            Out.Pickups.Add(Pickup);
                        }
                }
                else if (Kind == TEXT("hazard-damage"))
                {
                    Out.bHasHp = true;
                    if (M->TryGetNumberField(TEXT("startHp"), Num)) Out.StartHp = Num;
                    const TArray<TSharedPtr<FJsonValue>>* Hazards = nullptr;
                    if (M->TryGetArrayField(TEXT("hazards"), Hazards))
                        for (const TSharedPtr<FJsonValue>& HV : *Hazards)
                        {
                            const TSharedPtr<FJsonObject> HO = HV->AsObject();
                            if (!HO.IsValid()) continue;
                            FMojuloHazard Hazard;
                            ReadVec(HO, TEXT("at"), Hazard.Pos);
                            if (HO->TryGetNumberField(TEXT("radius"), Num)) Hazard.Radius = Num * 100.0;
                            if (HO->TryGetNumberField(TEXT("damage"), Num)) Hazard.Damage = Num;
                            Out.Hazards.Add(Hazard);
                        }
                }
                else if (Kind == TEXT("fail-on-death"))
                {
                    Out.bFailOnDeath = true;
                    if (!Out.bHasHp)
                    {
                        Out.bHasHp = true;
                        if (M->TryGetNumberField(TEXT("startHp"), Num)) Out.StartHp = Num;
                    }
                }
                else if (Kind == TEXT("survive"))
                {
                    Out.SurviveSeconds = 30.f;
                    if (M->TryGetNumberField(TEXT("seconds"), Num)) Out.SurviveSeconds = Num;
                }
                // Unknown kinds are skipped — ledgered pack-side, never fatal.
            }
        return true;
    }

    bool LoadGame(FMojuloGameData& Out)
    {
        const TSharedPtr<FJsonObject> Root = ParseFile(PackDir() / TEXT("game.json"));
        if (!Root.IsValid()) return false;
        Root->TryGetStringField(TEXT("title"), Out.Title);
        const TArray<TSharedPtr<FJsonValue>>* Levels = nullptr;
        if (Root->TryGetArrayField(TEXT("levels"), Levels))
            for (const TSharedPtr<FJsonValue>& V : *Levels)
            {
                const TSharedPtr<FJsonObject> L = V->AsObject();
                if (!L.IsValid()) continue;
                FMojuloGameLevel Level;
                L->TryGetStringField(TEXT("title"), Level.Title);
                L->TryGetStringField(TEXT("ref"), Level.Ref);
                const TSharedPtr<FJsonObject>* Gate = nullptr;
                if (L->TryGetObjectField(TEXT("gate"), Gate) && Gate->IsValid())
                    (*Gate)->TryGetStringField(TEXT("completed"), Level.GateCompleted);
                if (!Level.Ref.IsEmpty()) Out.Levels.Add(Level);
            }
        return true;
    }

    bool HasMenuMap()
    {
        return FPackageName::DoesPackageExist(MapPath(TEXT("mojulo-menu")));
    }

    TSet<FString> ReadCompleted()
    {
        TSet<FString> Done;
        FString Text;
        if (FFileHelper::LoadFileToString(Text, *ProgressPath()))
        {
            TArray<FString> Parts;
            Text.ParseIntoArray(Parts, TEXT("|"), true);
            for (const FString& Ref : Parts) Done.Add(Ref.TrimStartAndEnd());
        }
        return Done;
    }

    void MarkCompleted(const FString& LevelRef)
    {
        TSet<FString> Done = ReadCompleted();
        Done.Add(LevelRef);
        FFileHelper::SaveStringToFile(FString::Join(Done, TEXT("|")), *ProgressPath());
    }
}
